<?php

namespace Irios\WooCommerce\Tests;

use Brain\Monkey\Functions;
use Irios\WooCommerce\Settings;
use Irios\WooCommerce\SyncWebhooks;

/**
 * The product webhooks to the IRIOS Media sync service are set up by the plugin with nothing to configure: the URL comes
 * from the IRIOS Media domain and the Store ID, and the secret is generated by the plugin and read by the sync service
 * through its REST API key (GET /wp-json/irios/v1/sync).
 */
final class SyncWebhooksTest extends WordPressTestCase {

	private const URL = 'https://shop.iriosmedia.online/v1/webhooks/woocommerce/33';

	/** @var array<string,mixed> */
	private array $options = array();

	protected function setUp(): void {
		parent::setUp();
		\WC_Webhook::reset();
		$this->options  = array();
		$this->settings = array(
			'enabled'   => 'yes',
			'js_domain' => 'shop.iriosmedia.online',
			'store_id'  => '33',
		);
		Functions\when( 'get_option' )->alias(
			fn ( $name, $default = false ) => Settings::OPTION === $name ? $this->settings : ( $this->options[ $name ] ?? $default )
		);
		Functions\when( 'update_option' )->alias(
			function ( $name, $value ) {
				$this->options[ $name ] = $value;
				return true;
			}
		);
		Functions\when( 'delete_option' )->alias(
			function ( $name ) {
				unset( $this->options[ $name ] );
				return true;
			}
		);
		Functions\when( 'wc_get_webhook' )->alias( fn ( $id ) => \WC_Webhook::$saved[ (int) $id ] ?? false );
		Functions\when( 'current_user_can' )->justReturn( false );
		Functions\when( 'get_users' )->justReturn( array( 7 ) );
		Functions\when( 'wp_clear_scheduled_hook' )->justReturn( 0 );
	}

	/** @return array<string,\WC_Webhook> */
	private function by_topic(): array {
		$out = array();
		foreach ( \WC_Webhook::$saved as $webhook ) {
			$out[ $webhook->topic ] = $webhook;
		}
		return $out;
	}

	public function test_the_url_comes_from_the_irios_domain_and_the_store_id(): void {
		$this->assertSame( self::URL, SyncWebhooks::url( new Settings( $this->settings ) ) );
		$this->assertSame( '', SyncWebhooks::url( new Settings( array( 'enabled' => 'no' ) + $this->settings ) ) );
		$this->assertSame( '', SyncWebhooks::url( new Settings( array( 'store_id' => '' ) + $this->settings ) ) );
	}

	public function test_the_secret_is_generated_once_and_kept(): void {
		$secret = SyncWebhooks::secret();

		$this->assertMatchesRegularExpression( '/^[0-9a-f]{48}$/', $secret );
		$this->assertSame( $secret, SyncWebhooks::secret() );
	}

	public function test_one_active_webhook_per_product_topic_is_set_up_with_the_url_and_the_secret(): void {
		SyncWebhooks::maintain();

		$webhooks = $this->by_topic();
		$this->assertSame( array( 'product.created', 'product.updated', 'product.deleted' ), array_keys( $webhooks ) );
		foreach ( $webhooks as $topic => $webhook ) {
			$this->assertSame( 'IRIOS Media sync service: ' . $topic, $webhook->name );
			$this->assertSame( self::URL, $webhook->delivery_url );
			$this->assertSame( SyncWebhooks::secret(), $webhook->secret );
			$this->assertSame( 'wp_api_v3', $webhook->api_version );
			$this->assertSame( 'active', $webhook->status );
			$this->assertSame( 7, $webhook->user_id ); // no admin in this request (hourly check): the first one
		}
	}

	public function test_a_disabled_webhook_is_turned_back_on_and_a_new_domain_updates_them(): void {
		SyncWebhooks::maintain();
		$this->by_topic()['product.updated']->status = 'disabled'; // WooCommerce, after 5 failed deliveries
		$this->settings['js_domain'] = 'other.iriosmedia.online';
		Settings::forget();

		SyncWebhooks::maintain();

		$this->assertCount( 3, \WC_Webhook::$saved );
		$updated = $this->by_topic()['product.updated'];
		$this->assertSame( 'active', $updated->status );
		$this->assertSame( 'https://other.iriosmedia.online/v1/webhooks/woocommerce/33', $updated->delivery_url );
	}

	public function test_without_irios_media_enabled_they_are_removed_and_the_store_webhooks_stay(): void {
		$own = new \WC_Webhook();
		$own->set_name( 'Order export' );
		$own->set_topic( 'order.created' );
		$own->save();
		SyncWebhooks::maintain();
		$this->settings['enabled'] = 'no';
		Settings::forget();

		SyncWebhooks::maintain();

		$this->assertSame( array( 'Order export' ), array_map( fn ( $w ) => $w->name, array_values( \WC_Webhook::$saved ) ) );
	}

	public function test_a_duplicate_of_its_own_webhook_is_removed(): void {
		SyncWebhooks::maintain();
		$copy = new \WC_Webhook();
		$copy->set_name( 'IRIOS Media sync service: product.updated' );
		$copy->set_topic( 'product.updated' );
		$copy->save();

		SyncWebhooks::maintain();

		$this->assertCount( 3, \WC_Webhook::$saved ); // otherwise every change would be sent twice
	}

	public function test_on_admin_pages_they_are_only_set_up_again_when_something_changed(): void {
		SyncWebhooks::maintain_if_changed();
		$this->assertCount( 3, \WC_Webhook::$saved );
		\WC_Webhook::reset(); // if it ran again, it would create them again

		SyncWebhooks::maintain_if_changed();
		$this->assertCount( 0, \WC_Webhook::$saved );

		$this->settings['store_id'] = '34';
		Settings::forget();
		SyncWebhooks::maintain_if_changed();
		$this->assertCount( 3, \WC_Webhook::$saved );
	}

	public function test_the_sync_service_reads_the_url_the_secret_and_the_status(): void {
		SyncWebhooks::maintain();
		$this->by_topic()['product.deleted']->status = 'disabled';

		$data = SyncWebhooks::response()->get_data();

		$this->assertSame( self::URL, $data['webhook_url'] );
		$this->assertSame( SyncWebhooks::secret(), $data['webhook_secret'] );
		$this->assertSame( 'disabled', $data['webhooks']->{'product.deleted'} );
		$this->assertStringContainsString( 'product.deleted (disabled)', SyncWebhooks::status( new Settings( $this->settings ) ) );
	}

	public function test_without_the_settings_the_sync_service_gets_no_secret(): void {
		$this->settings['store_id'] = '';
		Settings::forget();

		$data = SyncWebhooks::response()->get_data();

		$this->assertNull( $data['webhook_url'] );
		$this->assertNull( $data['webhook_secret'] );
	}
}
